def is_palindrome(s):
    s = s.lower()
    return s == s[::-1]

def remove_duplicates(lst):
    seen = set()
    out = []
    for x in lst:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

def factorial(n):
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

def second_largest(nums):
    unique = sorted(set(nums), reverse=True)
    return unique[1] if len(unique) >= 2 else None

def average(nums):
    if not nums:
        return 0
    return sum(nums) / len(nums)

def fact(n):
    if n <= 1: return 1
    return n * fact(n - 1)

def append_to(item, target=None):
    if target is None:
        target = []
    target.append(item)
    return target

def swap_keys(d, k1, k2):
    res = dict(d)
    if k1 in res and k2 in res:
        res[k1], res[k2] = res[k2], res[k1]
    return res

def safe_cast_int(val, default=0):
    try:
        return int(val)
    except (ValueError, TypeError):
        return default
